#include "exec_private.h"
#include <stdarg.h>

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
  
void exec_q_insert (Exec_Q_Msg * exec_q_msg, Exec_Func exec_func , ...)
{	
	va_list args ;
	
	va_start( args , exec_func ) ;
	{
		exec_q_msg->arg = (Exec_Arg)va_arg( args , VARG ) ;
		exec_q_msg->cmd = (Exec_Arg)va_arg( args , VARG ) ; 
	}
	va_end( args ) ; 
	
	exec_q_msg->func = exec_func ;
		
	if( exec_q_pending )
	{
		q_insert (exec_q_pending , (Q_Msg *) exec_q_msg) ;
	}
}

